# Array-based O(1) lookup for prime factors: (a2, a3, a5, a7)
FACT = [
    (0, 0, 0, 0), # 0 (dummy, unreached for non-zero digits)
    (0, 0, 0, 0), # 1
    (1, 0, 0, 0), # 2
    (0, 1, 0, 0), # 3
    (2, 0, 0, 0), # 4
    (0, 0, 1, 0), # 5
    (1, 1, 0, 0), # 6
    (0, 0, 0, 1), # 7
    (3, 0, 0, 0), # 8
    (0, 2, 0, 0), # 9
]

@lru_cache(maxsize=None)
def dp_any(rem: int, csum: int, a2: int, a3: int, a5: int, a7: int, has_zero: bool) -> int:
    """
    Computes permutations of remaining digits without 'tight' bounds.
    Cache is globally shared between count(r) and count(l - 1).
    """
    if rem == 0:
        if has_zero:
            # csum > 0 is guaranteed by the digit DP mechanics
            return 1
        prod = (1 << a2) * (3 ** a3) * (5 ** a5) * (7 ** a7)
        return 1 if prod % csum == 0 else 0

    res = 0
    if has_zero:
