            res += dp_any(rem - 1, csum + d, 0, 0, 0, 0, True)
    else:
        # If d == 0, we found our first zero. Prime factor tracking becomes irrelevant.
        res += dp_any(rem - 1, csum, 0, 0, 0, 0, True)

